<template><section class="v2-page therapist-v2-page"><div v-if="loading" class="v2-state">正在打开患者工作区…</div><div v-else-if="error && !workspace" class="v2-state v2-state-error">{{ error }}</div><template v-else-if="workspace"><header class="workspace-lead"><div><RouterLink to="/therapist/patients" class="v2-text-link">← 返回患者</RouterLink><p class="v2-context">患者工作区</p><h1>{{ workspace.patient.username }}</h1><p>{{ workspace.rehabilitation_goal?.description || '尚未建立正式康复目标。' }}</p></div><div class="workspace-primary"><span>当前训练重点</span><strong>{{ workspace.active_training_plan?.stage_focus || '尚无有效训练方案' }}</strong><small v-if="workspace.active_training_plan">计划 v{{ workspace.active_training_plan.version_number }}</small></div></header><div v-if="error" class="v2-inline-error" role="alert">{{ error }}</div><nav class="workspace-anchor-nav" aria-label="患者工作区章节"><a href="#overview">概览</a><a href="#history">训练记录</a><a href="#assessment">正式评估</a><a href="#reviews">阶段复核</a></nav><section id="overview" class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">现在在练什么</p><h2>当前目标与训练方案</h2></div><RouterLink class="v2-button secondary" :to="`/therapist/plans?patient=${workspace.patient.user_id}`">管理训练方案</RouterLink></div><div class="workspace-overview-grid"><dl><div><dt>康复目标</dt><dd>{{ workspace.rehabilitation_goal?.description||'未建立' }}</dd></div><div><dt>阶段重点</dt><dd>{{ workspace.active_training_plan?.stage_focus||'未发布' }}</dd></div><div><dt>训练频率</dt><dd>{{ workspace.active_training_plan?.strategy?.frequency||'—' }}</dd></div></dl><div class="adherence-block"><strong>{{ workspace.training_adherence.completed_count }}</strong><span>已完成正式训练</span><small>共开始 {{ workspace.training_adherence.formal_session_count }} 次</small></div></div></section><section class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">需要处理</p><h2>开放的关注事项</h2></div></div><p v-if="!workspace.open_attention_items.length" class="v2-quiet-copy">当前没有开放事项。</p><div v-else class="attention-compact-list"><article v-for="item in workspace.open_attention_items" :key="item.id"><strong>{{ item.summary }} <em v-if="item.trigger_facts?.source_status==='mock'" class="demo-label">演示数据</em></strong><span>{{ item.priority }}</span></article></div></section><section id="history" class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">训练历史</p><h2>最近发生了什么</h2></div></div><div class="history-table"><RouterLink v-for="item in workspace.training_history" :key="item.id" :to="`/therapist/training-sessions/${item.id}`"><time>{{ item.date||'历史记录' }}</time><span>{{ item.kind==='formal'?'正式训练':'额外练习' }}</span><strong>{{ item.status }}</strong><ChevronRight aria-hidden="true"/></RouterLink></div></section><section id="assessment" class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">正式评估</p><h2>量表与专业施测</h2></div><RouterLink class="v2-button secondary" :to="`/therapist/patients/${workspace.patient.user_id}/assessments/new`">录入正式评估</RouterLink></div><p v-if="!workspace.formal_assessments.length" class="v2-quiet-copy">尚无正式评估记录。日常训练指标不会自动当作正式量表结果。</p><ul class="plain-fact-list"><li v-for="item in workspace.formal_assessments" :key="item.id"><strong>{{ item.instrument||'未命名量表' }} <em v-if="String(item.instrument).startsWith('DEMO-')" class="demo-label">演示数据</em></strong><span>{{ item.version||'版本未记录' }} · {{ item.review_status }}</span></li></ul></section><section id="reviews" class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">阶段决策</p><h2>Stage Review</h2></div><button class="v2-button primary" :disabled="busy" @click="startReview">{{ busy?'正在创建…':'创建阶段复核' }}</button></div><p v-if="!workspace.stage_reviews.length" class="v2-quiet-copy">还没有阶段复核。</p><div class="history-table"><RouterLink v-for="item in workspace.stage_reviews" :key="item.id" :to="`/therapist/stage-reviews/${item.id}`"><time>{{ formatDate(item.created_at) }}</time><span>{{ item.status }}</span><strong>查看事实与决策</strong><ChevronRight/></RouterLink></div></section></template></section></template>
<script setup lang="ts">import { onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ChevronRight } from 'lucide-vue-next';import { v2Api } from '@/api/v2';import { toUserMessage } from '@/utils/errors';const route=useRoute();const router=useRouter();const workspace=ref<any>(null);const loading=ref(true);const busy=ref(false);const error=ref('');async function load(){loading.value=true;error.value='';try{workspace.value=await v2Api.workspace(String(route.params.patientId))}catch(err){error.value=toUserMessage(err,'患者工作区加载失败。')}finally{loading.value=false}}async function startReview(){if(busy.value)return;busy.value=true;error.value='';try{const review=await v2Api.createStageReview(String(route.params.patientId));const attention=String(route.query.attention||'');await router.push({path:`/therapist/stage-reviews/${review.id}`,query:attention?{attention}:undefined})}catch(err){error.value=toUserMessage(err,'阶段复核创建失败。')}finally{busy.value=false}}function formatDate(value:string){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(value))}onMounted(load);</script>
